#include <bits/stdc++.h>
using namespace std;
#define MAXN 15000
#define MAXE 200000

struct Edge {
    int to, cap, flow, cost;
};

Edge e[MAXE];
int head[MAXN], nxt[MAXE], edge_cnt = 0;
long long ans, dis[MAXN];
int n, m, k, c, d, p[MAXN], pe[MAXN], inq[MAXN], s = 9998, t = 9999;

void add_edge(int x, int y, int cap, int cost) {
    e[edge_cnt] = {y, cap, 0, cost};
    nxt[edge_cnt] = head[x];
    head[x] = edge_cnt++;
    e[edge_cnt] = {x, 0, 0, -cost};
    nxt[edge_cnt] = head[y];
    head[y] = edge_cnt++;
}

void push_rebel() {
    fill(dis, dis + 10000, (long long)1e18);
    fill(p, p + 10000, -1);
    fill(pe, pe + 10000, -1);
    fill(inq, inq + 10000, 0);
    dis[s] = 0;
    queue<int> q;
    q.push(s);
    inq[s] = 1;
    while (!q.empty()) {
        int k = q.front(); q.pop();
        inq[k] = 0;
        for (int i = head[k]; i != -1; i = nxt[i]) {
            if (!(e[i].cap - e[i].flow)) continue;
            int c = e[i].cost, y = e[i].to;
            if (dis[y] > dis[k] + c) {
                dis[y] = dis[k] + c;
                p[y] = k;
                pe[y] = i;
                if (!inq[y]) {
                    inq[y] = 1;
                    q.push(y);
                }
            }
        }
    }
    int cur = t;
    while (cur != s) {
        e[pe[cur]].flow++;
        e[pe[cur] ^ 1].flow--;
        cur = p[cur];
    }
    ans += dis[t];
}

int main() {
    scanf("%d%d%d%d%d", &n, &m, &k, &c, &d);
    memset(head, -1, sizeof(head));
    int x, y;
    for (int i = 1; i <= k; i++) {
        scanf("%d", &x);
        x--;
        add_edge(s, x, 1, 0);
    }
    for (int i = 1; i <= 101; i++)
        add_edge((i - 1) * n, t, k, (i - 1) * c);
    for (int i = 1; i <= m; i++) {
        scanf("%d%d", &x, &y);
        x--; y--;
        for (int i = 1; i <= 100; i++)
            for (int j = 1; j <= k; j++) {
                add_edge(x + (i - 1) * n, y + (i - 1) * n + n, 1, d * ((j - 1) * 2 + 1));
                add_edge(y + (i - 1) * n, x + (i - 1) * n + n, 1, d * ((j - 1) * 2 + 1));
            }
    }
    for (int i = 1; i <= n; i++)
        for (int j = 1; j <= 100; j++)
            add_edge(i - 1 + (j - 1) * n, i - 1 + (j - 1) * n + n, k, 0);
    for (int i = 1; i <= k; i++) push_rebel();
    printf("%lld\n", ans);
    return 0;
}
